  "inlineSchema": "// Prisma schema for floorplan-ai backend\n// Database: PostgreSQL (via @prisma/adapter-pg)\n//\n// HDB Hierarchy: Town → Project → FlatType → LayoutVariant → Walls/Rooms\n//\n// FlatType = HDB room category (e.g. \"4-Room\" = 3 bedrooms + living/dining)\n// LayoutVariant = specific floor plan within a flat type\n//   (e.g. 2-Room Flexi has Type 1 and Type 2 variants;\n//    newer projects offer \"Standard\" vs \"White Flat\" open-concept layouts)\n//\n// HDB terminology: room count INCLUDES the living room.\n//   4-Room = 3 bedrooms, 3-Room = 2 bedrooms, etc.\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─── Auth ────────────────────────────────────────────────────────\n\nmodel User {\n  id        String   @id @default(uuid())\n  googleId  String   @unique\n  email     String   @unique\n  name      String\n  avatarUrl String?\n  role      String   @default(\"user\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ─── BTO Projects ───────────────────────────────────────────────\n\nmodel BTOProject {\n  id             String     @id @default(cuid())\n  name           String\n  slug           String     @unique\n  description    String?\n  town           String // HDB town: \"Kallang\", \"Tampines\", \"Queenstown\", etc.\n  location       String // Display location: \"Kallang\", \"Tampines North\", etc.\n  launchYear     Int\n  classification String     @default(\"standard\") // \"standard\" | \"plus\" | \"prime\" (HDB Oct 2024 framework)\n  developer      String     @default(\"HDB\")\n  imageUrl       String?\n  published      Boolean    @default(false)\n  flatTypes      FlatType[]\n  createdAt      DateTime   @default(now())\n  updatedAt      DateTime   @updatedAt\n\n  @@index([published, launchYear])\n  @@index([town])\n}\n\n// ─── Flat Types (HDB room categories) ────────────────────────────\n\nmodel FlatType {\n  id             String          @id @default(cuid())\n  btoProjectId   String\n  btoProject     BTOProject      @relation(fields: [btoProjectId], references: [id], onDelete: Cascade)\n  name           String // \"2-Room Flexi\", \"3-Room\", \"4-Room\", \"5-Room\", \"3Gen\"\n  bedroomCount   Int // Derived: 2-Room=1, 3-Room=2, 4-Room=3, 5-Room=3, 3Gen=4\n  typicalSizeMin Float? // sqm (e.g. 89 for 4-room)\n  typicalSizeMax Float? // sqm (e.g. 94 for 4-room)\n  sortOrder      Int             @default(0)\n  variants       LayoutVariant[]\n  createdAt      DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n\n  @@index([btoProjectId])\n}\n\n// ─── Layout Variants (specific floor plans within a flat type) ───\n\nmodel LayoutVariant {\n  id           String        @id @default(cuid())\n  flatTypeId   String\n  flatType     FlatType      @relation(fields: [flatTypeId], references: [id], onDelete: Cascade)\n  name         String // \"Standard\", \"White Flat\", \"Type 1\", \"Type 2\"\n  floorPlanUrl String? // Uploaded floor plan image\n  thumbnailUrl String?\n  totalArea    Float? // sqm for this specific variant\n  isWhiteFlat  Boolean       @default(false) // Open-concept, no internal partition walls\n  published    Boolean       @default(false)\n  sortOrder    Int           @default(0)\n  walls        WallSegment[]\n  roomDefs     RoomDef[]\n  furniture    Json?\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n\n  @@index([flatTypeId, published])\n}\n\n// ─── Walls ───────────────────────────────────────────────────────\n\nmodel WallSegment {\n  id              String        @id @default(cuid())\n  layoutVariantId String\n  layoutVariant   LayoutVariant @relation(fields: [layoutVariantId], references: [id], onDelete: Cascade)\n\n  // 2D coordinates on the floor plan (metres from origin)\n  startX Float\n  startY Float\n  endX   Float\n  endY   Float\n\n  // Physical properties (HDB standards: structural 100-150mm, partition 75-100mm)\n  thickness     Float   @default(0.10) // 100mm non-structural wall\n  height        Float   @default(2.6) // HDB ceiling height\n  wallType      String  @default(\"internal\") // \"internal\" | \"external\" | \"party\"\n  isLoadBearing Boolean @default(false)\n\n  // Adjacency: which rooms are on each side\n  // \"positive\" = right-hand side of directed edge (start → end)\n  // \"negative\" = left-hand side of directed edge (start → end)\n  positiveRoomId String?\n  positiveRoom   RoomDef? @relation(\"positiveRoom\", fields: [positiveRoomId], references: [id])\n  negativeRoomId String?\n  negativeRoom   RoomDef? @relation(\"negativeRoom\", fields: [negativeRoomId], references: [id])\n\n  // Openings in this wall\n  doors   DoorOpening[]\n  windows WindowOpening[]\n\n  // Admin metadata\n  sortOrder Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([layoutVariantId])\n}\n\n// ─── Door Openings ───────────────────────────────────────────────\n\nmodel DoorOpening {\n  id            String      @id @default(cuid())\n  wallSegmentId String\n  wallSegment   WallSegment @relation(fields: [wallSegmentId], references: [id], onDelete: Cascade)\n\n  // Position along the wall (percentage from start to end, 0.0-1.0)\n  position Float // 0.0 = at start, 1.0 = at end\n  width    Float  @default(0.9) // metres\n  height   Float  @default(2.1) // metres\n  swing    String @default(\"in\") // \"in\" | \"out\"\n  hinge    String @default(\"left\") // \"left\" | \"right\"\n  doorType String @default(\"swing\") // \"swing\" | \"folding\"\n  length   Float?\n\n  @@index([wallSegmentId])\n}\n\n// ─── Window Openings ─────────────────────────────────────────────\n\nmodel WindowOpening {\n  id            String      @id @default(cuid())\n  wallSegmentId String\n  wallSegment   WallSegment @relation(fields: [wallSegmentId], references: [id], onDelete: Cascade)\n\n  position Float // 0.0-1.0 along wall\n  width    Float @default(1.2)\n\n  @@index([wallSegmentId])\n}\n\n// ─── Rooms (Derived from Walls) ──────────────────────────────────\n\nmodel RoomDef {\n  id              String        @id @default(cuid())\n  layoutVariantId String\n  layoutVariant   LayoutVariant @relation(fields: [layoutVariantId], references: [id], onDelete: Cascade)\n\n  label            String // \"Living Room\", \"Master Bedroom\"\n  roomType         String  @default(\"bedroom\") // \"living\" | \"bedroom_master\" | \"bedroom\" | \"kitchen\" | \"toilet\" | \"bomb_shelter\" | \"service_yard\" | \"hallway\" | \"balcony\"\n  originalRoomType String? // What admin originally labelled (for reference after wall edits)\n  area             Float? // Room area in sqm (e.g. 14.5 for Master Bedroom)\n\n  // Material defaults\n  defaultWallColor  String @default(\"#F5F5F0\")\n  defaultFloorType  String @default(\"parquet\")\n  defaultFloorColor String @default(\"#C4A882\")\n\n  // Wall adjacency (reverse relations)\n  positiveWalls WallSegment[] @relation(\"positiveRoom\")\n  negativeWalls WallSegment[] @relation(\"negativeRoom\")\n\n  sortOrder Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([layoutVariantId])\n}\n",
